256: /// assert!(!is_meta_character('%'));
257: /// assert!(!is_meta_character('/'));
258: /// assert!(!is_meta_character('!'));
259: /// assert!(!is_meta_character('"'));
260: /// assert!(!is_meta_character('e'));
261: /// ```
